import"./chunk-VC46IEJQ.js";var e=(a,o,t,s,n,i,r,h,l,d,f={})=>({id:a,kind:o,region:t,at:s,rank:n,names:i,alt:r,summary:h,refs:l,confidence:d,...f}),m={group:"essos-east",places:[{id:"vaes-dothrak",houses:[],refs:["agot","twoiaf"],confidence:"high",summary:{en:"The one city of the horse-lords, raised beneath the Mother of Mountains and entered through a gate of two bronze stallions. Its avenue is lined with the stolen gods and monuments of conquered peoples, and its halls stand mostly empty until the khalasars come. The crones of the dosh khaleen rule here, and no blood may be shed within its bounds.",zh:"\u9A6C\u738B\u4EEC\u552F\u4E00\u7684\u57CE\u5E02\uFF0C\u5EFA\u5728\u7FA4\u5C71\u4E4B\u6BCD\u811A\u4E0B\uFF0C\u5165\u57CE\u987B\u7A7F\u8FC7\u4E00\u5BF9\u9752\u94DC\u9A8F\u9A6C\u6784\u6210\u7684\u57CE\u95E8\u3002\u795E\u8DEF\u4E24\u65C1\u9648\u5217\u7740\u4ECE\u88AB\u5F81\u670D\u6C11\u65CF\u63A0\u6765\u7684\u795E\u50CF\u4E0E\u53E4\u8FF9\uFF1B\u5E73\u65E5\u6BBF\u5B87\u5927\u591A\u7A7A\u7F6E\uFF0C\u53EA\u5F85\u5404\u5361\u62C9\u8428\u524D\u6765\u3002\u591A\u65AF\u5361\u6797\u7684\u8001\u59AA\u5728\u6B64\u4E3B\u4E8B\uFF0C\u57CE\u5185\u4E25\u7981\u6D41\u8840\u3002"}},{id:"astapor",houses:["nakloz"],refs:["asos","adwd","twoiaf"],confidence:"high",summary:{en:"A red-brick Ghiscari city on the Worm, at the southern end of Slaver's Bay. Its Good Masters grew rich by breeding, gelding and drilling the Unsullied, slave infantry famed for perfect obedience. A great brick harpy once stood in its Plaza of Pride.",zh:"\u5974\u96B6\u6E7E\u5357\u7AEF\u3001\u8815\u866B\u6CB3\u7554\u7684\u5409\u65AF\u5361\u5229\u7EA2\u7816\u4E4B\u57CE\u3002\u57CE\u4E2D\u7684\u5584\u4E3B\u9760\u57F9\u80B2\u3001\u9609\u5272\u548C\u64CD\u7EC3\u65E0\u57A2\u8005\u81F4\u5BCC\uFF0C\u8FD9\u79CD\u5974\u96B6\u6B65\u5175\u4EE5\u7EDD\u5BF9\u670D\u4ECE\u95FB\u540D\u3002\u9A84\u50B2\u5E7F\u573A\u4E0A\u66FE\u77D7\u7ACB\u7740\u4E00\u5C0A\u5DE8\u5927\u7684\u7816\u780C\u9E70\u8EAB\u5973\u5996\u50CF\u3002"},spoiler:{en:"Daenerys bought the Unsullied here, then turned them on their masters and sacked the city (ASOS). Under the butcher king Cleon and his successors Astapor fell into bloodshed and plague (ADWD).",zh:"\u4E39\u59AE\u8389\u4E1D\u5728\u6B64\u4E70\u4E0B\u65E0\u57A2\u8005\uFF0C\u968F\u5373\u547D\u4ED6\u4EEC\u53CD\u6208\u653B\u6740\u4E3B\u4EBA\uFF0C\u6D17\u52AB\u4E86\u57CE\u5E02\uFF08\u5377\u4E09\uFF09\u3002\u6B64\u540E\u5728\u201C\u5C60\u592B\u738B\u201D\u514B\u83B1\u6602\u53CA\u5176\u7EE7\u4EFB\u8005\u6CBB\u4E0B\uFF0C\u963F\u65AF\u5854\u6CE2\u9677\u5165\u6740\u622E\u4E0E\u761F\u75AB\uFF08\u5377\u4E94\uFF09\u3002"}},{id:"yunkai",houses:["qaggaz","eraz"],refs:["asos","adwd","twoiaf"],confidence:"high",summary:{en:"The Yellow City, smaller and older than its neighbours, walled in crumbling yellow brick between Astapor and Meereen. Its Wise Masters train bed-slaves and hire sellsword companies rather than keep great armies of their own.",zh:"\u201C\u9EC4\u57CE\u201D\uFF0C\u4F4D\u4E8E\u963F\u65AF\u5854\u6CE2\u4E0E\u5F25\u6797\u4E4B\u95F4\uFF0C\u57CE\u5899\u662F\u5265\u843D\u7684\u9EC4\u7816\uFF0C\u6BD4\u4E24\u5EA7\u90BB\u57CE\u66F4\u5C0F\u4E5F\u66F4\u53E4\u8001\u3002\u57CE\u4E2D\u7684\u667A\u8005\u4EE5\u8C03\u6559\u5E8A\u5974\u4E3A\u4E1A\uFF0C\u5B81\u613F\u96C7\u4F63\u4F63\u5175\u56E2\uFF0C\u4E5F\u4E0D\u613F\u81EA\u517B\u5927\u519B\u3002"},spoiler:{en:"Daenerys forced Yunkai to free its slaves (ASOS); afterwards the Yunkai'i raised a coalition of Ghiscari and sellswords and laid siege to Meereen (ADWD).",zh:"\u4E39\u59AE\u8389\u4E1D\u8FEB\u4F7F\u6E0A\u51EF\u91CA\u653E\u5974\u96B6\uFF08\u5377\u4E09\uFF09\uFF1B\u5176\u540E\u6E0A\u51EF\u4EBA\u7EA0\u96C6\u5409\u65AF\u5361\u5229\u8BF8\u57CE\u4E0E\u4F63\u5175\u56E2\uFF0C\u56F4\u653B\u5F25\u6797\uFF08\u5377\u4E94\uFF09\u3002"}},{id:"meereen",houses:["loraq","pahl","galare","merreq","ghazeen","rhazdar","zhak","hazkar","uhlez","kandaq","reznak"],refs:["asos","adwd","twoiaf"],confidence:"high",summary:{en:`The largest and proudest of the Slaver cities, at the mouth of the Skahazadhan. Its old families live in stepped brick pyramids, the Great Pyramid rising highest of all, and its fighting pits draw crowds to Daznak's Pit and lesser arenas. Meereenese nobles bear the honorific "zo" before their family name.`,zh:"\u5974\u96B6\u6E7E\u8BF8\u57CE\u4E2D\u6700\u5927\u3001\u6700\u9A84\u50B2\u7684\u4E00\u5EA7\uFF0C\u5750\u843D\u4E8E\u65AF\u5361\u54C8\u624E\u4E39\u6CB3\u53E3\u3002\u65E7\u8D35\u65CF\u4E16\u5C45\u9636\u68AF\u72B6\u7684\u7816\u780C\u91D1\u5B57\u5854\uFF0C\u5176\u4E2D\u4EE5\u5927\u91D1\u5B57\u5854\u6700\u9AD8\uFF1B\u8FBE\u5179\u7EB3\u514B\u7ADE\u6280\u573A\u7B49\u89D2\u6597\u573A\u5E38\u5E74\u4EBA\u58F0\u9F0E\u6CB8\u3002\u5F25\u6797\u8D35\u65CF\u5728\u5BB6\u65CF\u540D\u524D\u51A0\u4EE5\u201C\u4F50\u201D\uFF08zo\uFF09\u5B57\u3002"},spoiler:{en:"Daenerys took the city at the end of ASOS and chose to stay and rule it; in ADWD she wed Hizdahr zo Loraq to buy peace while the Yunkai'i besieged the city and the Sons of the Harpy murdered her freedmen.",zh:"\u5377\u4E09\u672B\u4E39\u59AE\u8389\u4E1D\u653B\u4E0B\u5F25\u6797\u5E76\u51B3\u5B9A\u7559\u4E0B\u7EDF\u6CBB\uFF1B\u5377\u4E94\u4E2D\u6E0A\u51EF\u4EBA\u5175\u4E34\u57CE\u4E0B\u3001\u9E70\u8EAB\u5973\u5996\u4E4B\u5B50\u6697\u6740\u81EA\u7531\u6C11\uFF0C\u5979\u4E3A\u6362\u53D6\u548C\u5E73\u5AC1\u7ED9\u4E86\u5E0C\u5179\u8FBE\u5C14\xB7\u4F50\xB7\u6D1B\u62C9\u514B\u3002"}},{id:"qarth",houses:[],refs:["acok","twoiaf"],confidence:"high",summary:{en:"An ancient, wealthy port commanding the straits between the Summer Sea and the Jade Sea. Three great walls carved with scenes ring the city, and power is shared uneasily among the Pureborn, the merchant guilds such as the Thirteen, and the warlocks of the House of the Undying.",zh:"\u627C\u5B88\u590F\u65E5\u4E4B\u6D77\u4E0E\u7389\u6D77\u4E4B\u95F4\u6D77\u5CE1\u7684\u53E4\u8001\u5BCC\u6E2F\u3002\u4E09\u9053\u96D5\u6EE1\u56FE\u666F\u7684\u5DE8\u5899\u73AF\u7ED5\u5168\u57CE\uFF1B\u6743\u529B\u7531\u7EAF\u8840\u8005\u3001\u201C\u5341\u4E09\u5DE8\u5934\u201D\u7B49\u5546\u4EBA\u516C\u4F1A\u4EE5\u53CA\u4E0D\u673D\u8005\u4E4B\u6BBF\u7684\u672F\u58EB\u4EEC\u52C9\u5F3A\u5206\u4EAB\u3002"},spoiler:{en:"Daenerys spent much of ACOK here seeking ships and allies; she left after burning the House of the Undying.",zh:"\u5377\u4E8C\u4E2D\u4E39\u59AE\u8389\u4E1D\u5728\u6B64\u9017\u7559\u826F\u4E45\uFF0C\u5BFB\u6C42\u8239\u53EA\u4E0E\u76DF\u53CB\uFF1B\u5979\u5728\u711A\u6BC1\u4E0D\u673D\u8005\u4E4B\u6BBF\u540E\u79BB\u5F00\u3002"}},{id:"valyria",houses:[],refs:["agot","adwd","twoiaf"],confidence:"high",summary:{en:"Heart of the Freehold of Valyria, the dragonlord empire that ruled much of Essos for five thousand years. Around four centuries before the novels it was destroyed in a single cataclysm, the Doom; the peninsula shattered and the Smoking Sea rushed in. Sailors hold that any who seek its ruins never return.",zh:"\u74E6\u96F7\u5229\u4E9A\u81EA\u7531\u5821\u5792\u7684\u5FC3\u810F\uFF0C\u8FD9\u4E2A\u9F99\u738B\u5E1D\u56FD\u66FE\u7EDF\u6CBB\u5384\u7D22\u65AF\u5927\u90E8\u8FBE\u4E94\u5343\u5E74\u3002\u7EA6\u56DB\u767E\u5E74\u524D\uFF0C\u5B83\u5728\u4E00\u573A\u540D\u4E3A\u201C\u672B\u65E5\u6D69\u52AB\u201D\u7684\u707E\u53D8\u4E2D\u6BC1\u4E8E\u4E00\u65E6\uFF0C\u534A\u5C9B\u5D29\u88C2\uFF0C\u70DF\u6D77\u5012\u704C\u3002\u6C34\u624B\u4EEC\u76F8\u4F20\uFF0C\u524D\u5F80\u5BFB\u8BBF\u5E9F\u589F\u7684\u4EBA\u4ECE\u672A\u5F52\u6765\u3002"}},{id:"asshai",houses:[],refs:["agot","acok","twoiaf"],confidence:"medium",summary:{en:"A vast and nearly lifeless port on the edge of the Shadow, built entirely of black stone and as old as any city in the world. Few children are born there and nothing grows, yet ships come from everywhere to trade, and shadowbinders, warlocks and red priests come to learn its secrets.",zh:"\u9634\u5F71\u5C71\u8109\u8FB9\u7F18\u4E00\u5EA7\u5E7F\u5927\u800C\u51E0\u4E4E\u6B7B\u5BC2\u7684\u6E2F\u53E3\uFF0C\u5168\u57CE\u4EE5\u9ED1\u77F3\u5EFA\u6210\uFF0C\u53E4\u8001\u7A0B\u5EA6\u4E0D\u4E9A\u4E8E\u4E16\u4E0A\u4EFB\u4F55\u57CE\u5E02\u3002\u57CE\u4E2D\u5C11\u6709\u5A74\u513F\u964D\u751F\uFF0C\u5BF8\u8349\u4E0D\u751F\uFF0C\u4F46\u5404\u5730\u5546\u8239\u4ECD\u8FDC\u9053\u800C\u6765\uFF1B\u7F1A\u5F71\u58EB\u3001\u672F\u58EB\u4E0E\u7EA2\u888D\u50E7\u4E5F\u7EB7\u7EB7\u524D\u6765\u6C42\u5B66\u79D8\u672F\u3002"}},{id:"yin",houses:[],refs:["twoiaf"],confidence:"low",summary:{en:"Seat of the God-Emperor of Yi Ti, the old and sprawling eastern empire beyond the Bone Mountains. The novels mention Yi Ti only in passing; what is known of its capital and its rival emperors comes mostly from the world history.",zh:"\u5937\u5730\u795E\u7687\u7684\u90FD\u57CE\u3002\u5937\u5730\u662F\u9AB8\u9AA8\u5C71\u8109\u4EE5\u4E1C\u4E00\u4E2A\u53E4\u8001\u800C\u8FBD\u9614\u7684\u5E1D\u56FD\uFF0C\u5C0F\u8BF4\u4E2D\u4EC5\u4E00\u7B14\u5E26\u8FC7\uFF1B\u5173\u4E8E\u5176\u90FD\u57CE\u4E0E\u5386\u4EE3\u4E89\u7ACB\u7684\u7687\u5E1D\uFF0C\u6240\u77E5\u5927\u591A\u51FA\u81EA\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002"}},{id:"port-of-ibben",houses:[],refs:["agot","affc","twoiaf"],confidence:"medium",summary:{en:"The chief harbour of Ibben, a cold island in the Shivering Sea. Its stocky, heavily bearded people are whalers and traders whose ships call at Braavos and the ports of the north.",zh:"\u4F0A\u73ED\u7684\u4E3B\u8981\u6E2F\u53E3\uFF0C\u4F0A\u73ED\u662F\u98A4\u6296\u6D77\u4E2D\u4E00\u5EA7\u5BD2\u51B7\u7684\u5C9B\u5C7F\u3002\u5C9B\u6C11\u8EAB\u6750\u77EE\u58EE\u3001\u987B\u53D1\u6D53\u5BC6\uFF0C\u4EE5\u6355\u9CB8\u548C\u7ECF\u5546\u4E3A\u4E1A\uFF0C\u8239\u53EA\u5E38\u5230\u5E03\u62C9\u4F5B\u65AF\u548C\u5317\u65B9\u5404\u6E2F\u3002"}},{id:"kayakayanaya",houses:[],refs:["agot","affc","twoiaf"],confidence:"medium",summary:{en:"Tall Trees Town, a port of the Summer Isles set among giant trees, and home port of the swan ships that carry Summer Islanders across the seas. The islanders are dark-skinned, wear bright feathered cloaks and are famed for their goldenheart longbows.",zh:"\u9AD8\u6811\u9547\uFF0C\u76DB\u590F\u7FA4\u5C9B\u7684\u6E2F\u53E3\uFF0C\u5750\u843D\u5728\u53C2\u5929\u5DE8\u6811\u4E4B\u95F4\uFF0C\u662F\u8F7D\u7740\u76DB\u590F\u7FA4\u5C9B\u5C9B\u6C11\u8FDC\u822A\u7684\u5929\u9E45\u8239\u7684\u6BCD\u6E2F\u3002\u5C9B\u6C11\u80A4\u8272\u9EDD\u9ED1\uFF0C\u8EAB\u62AB\u9C9C\u8273\u7684\u7FBD\u6BDB\u6597\u7BF7\uFF0C\u6240\u5236\u7684\u91D1\u5FC3\u6728\u957F\u5F13\u5929\u4E0B\u95FB\u540D\u3002"}},e("mother-of-mountains","mountain","dothraki-sea",[1564,726],3,{en:"Mother of Mountains",zh:"\u7FA4\u5C71\u4E4B\u6BCD"},["Mother of Mountains"],{en:"A lone mountain rising out of the grass sea, the holiest place of the Dothraki. Vaes Dothrak lies at its foot, and the khals climb it to make offerings; the Dothraki believe their people were born of it.",zh:"\u4ECE\u8349\u6D77\u4E2D\u5B64\u5CF0\u62D4\u8D77\u7684\u5927\u5C71\uFF0C\u662F\u591A\u65AF\u62C9\u514B\u4EBA\u6700\u795E\u5723\u7684\u5730\u65B9\u3002\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u5C31\u5728\u5C71\u811A\uFF0C\u5361\u5965\u4EEC\u767B\u5C71\u732E\u796D\uFF1B\u591A\u65AF\u62C9\u514B\u4EBA\u76F8\u4FE1\u672C\u65CF\u4FBF\u6E90\u51FA\u4E8E\u6B64\u3002"},["agot","twoiaf"],"high"),e("womb-of-the-world","lake","dothraki-sea",[1584,788],2,{en:"Womb of the World",zh:"\u4E16\u754C\u4E4B\u5B50\u5BAB"},["Womb of the World lake"],{en:"A sacred lake beside Vaes Dothrak, its waters said to be bottomless. The Dothraki hold that the first man rode out of it on the first horse, and khals and khaleesis bathe there in holy rites.",zh:"\u7EF4\u65AF\xB7\u591A\u65AF\u62C9\u514B\u65C1\u7684\u5723\u6E56\uFF0C\u76F8\u4F20\u6DF1\u4E0D\u89C1\u5E95\u3002\u591A\u65AF\u62C9\u514B\u4EBA\u8BA4\u4E3A\u7B2C\u4E00\u4E2A\u4EBA\u9A91\u7740\u7B2C\u4E00\u5339\u9A6C\u4ECE\u6E56\u4E2D\u800C\u51FA\uFF1B\u5361\u5965\u4E0E\u5361\u4E3D\u7199\u4F1A\u5728\u6B64\u4E3E\u884C\u6C90\u6D74\u7684\u5723\u793C\u3002"},["agot","twoiaf"],"high"),e("sarnath","ruin","dothraki-sea",[1330,590],2,{en:"Sarnath",zh:"\u8428\u6069\u7EB3\u65AF"},["Sarnath of the Tall Men","Sarnor","\u8428\u6069\u8BFA"],{en:'Capital of the vanished kingdom of Sarnor, whose "Tall Men" once held the northern grasslands. Its High King was overthrown when the Dothraki swept across the plains after the Doom, and the city was burned; only ruins remain.',zh:"\u5DF2\u6D88\u4EA1\u7684\u8428\u6069\u8BFA\u738B\u56FD\u7684\u90FD\u57CE\uFF0C\u201C\u9AD8\u4EBA\u201D\u66FE\u7EDF\u6CBB\u5317\u65B9\u8349\u539F\u3002\u672B\u65E5\u6D69\u52AB\u4E4B\u540E\u591A\u65AF\u62C9\u514B\u4EBA\u6A2A\u626B\u5E73\u539F\uFF0C\u8428\u6069\u8BFA\u81F3\u9AD8\u738B\u8986\u706D\uFF0C\u57CE\u5E02\u4ED8\u4E4B\u4E00\u70AC\uFF0C\u5982\u4ECA\u53EA\u4F59\u5E9F\u589F\u3002"},["twoiaf"],"low"),e("sathar","ruin","dothraki-sea",[1390,680],1,{en:"Sathar",zh:"\u8428\u8428\u5C14"},["Sarnor"],{en:"One of the cities of Sarnor, overrun and abandoned when the Dothraki destroyed that kingdom. Little more than its name and fate are recorded; the position shown here is approximate.",zh:"\u8428\u6069\u8BFA\u8BF8\u57CE\u4E4B\u4E00\uFF0C\u5728\u591A\u65AF\u62C9\u514B\u4EBA\u6467\u6BC1\u8BE5\u738B\u56FD\u65F6\u88AB\u653B\u9677\u3001\u8352\u5F03\u3002\u53F2\u6599\u51E0\u4E4E\u53EA\u7559\u4E0B\u5176\u540D\u5B57\u4E0E\u7ED3\u5C40\uFF0C\u56FE\u4E2D\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("kasath","ruin","dothraki-sea",[1210,600],1,{en:"Kasath",zh:"\u5361\u8428\u65AF"},["Sarnor"],{en:"A ruined Sarnori city in the north-west of the grasslands, one of those razed by the khalasars after the Doom. It is known only from the histories, and its placement here is a guess.",zh:"\u8349\u539F\u897F\u5317\u90E8\u7684\u4E00\u5EA7\u8428\u6069\u8BFA\u57CE\u5E02\u5E9F\u589F\uFF0C\u672B\u65E5\u6D69\u52AB\u540E\u4E3A\u5404\u5361\u62C9\u8428\u6240\u6BC1\u3002\u4EC5\u89C1\u4E8E\u53F2\u4E66\uFF0C\u56FE\u4E2D\u4F4D\u7F6E\u4E3A\u63A8\u6D4B\u3002"},["twoiaf"],"low"),e("kyth","ruin","dothraki-sea",[1258,680],1,{en:"Kyth",zh:"\u57FA\u65AF"},["Sarnor"],{en:"Another of the lost Sarnori cities, burned during the long Dothraki conquest of the grass sea. Only a name in the histories; the position is approximate.",zh:"\u53E6\u4E00\u5EA7\u6E6E\u706D\u7684\u8428\u6069\u8BFA\u57CE\u5E02\uFF0C\u5728\u591A\u65AF\u62C9\u514B\u4EBA\u6F2B\u957F\u7684\u5F81\u670D\u4E2D\u88AB\u711A\u6BC1\u3002\u53F2\u4E66\u4E2D\u4EC5\u5B58\u5176\u540D\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("mardosh","ruin","dothraki-sea",[1452,560],1,{en:"Mardosh",zh:"\u9A6C\u591A\u4EC0"},["Sarnor"],{en:"A Sarnori city lost to the Dothraki; according to the histories it was one of the last to fall. Nothing of it is described in the novels, and its location is approximate.",zh:"\u4E00\u5EA7\u843D\u5165\u591A\u65AF\u62C9\u514B\u4EBA\u4E4B\u624B\u7684\u8428\u6069\u8BFA\u57CE\u5E02\uFF0C\u636E\u53F2\u4E66\u8BB0\u8F7D\u662F\u6700\u540E\u9677\u843D\u7684\u51E0\u5EA7\u4E4B\u4E00\u3002\u5C0F\u8BF4\u672A\u66FE\u63CF\u5199\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("hornoth","ruin","dothraki-sea",[1520,524],1,{en:"Hornoth",zh:"\u970D\u8BFA\u65AF"},["Sarnor"],{en:"A ruined city of old Sarnor in the north-east of the grasslands, destroyed with the rest of that kingdom. Known only by name; position approximate.",zh:"\u8349\u539F\u4E1C\u5317\u90E8\u7684\u53E4\u8428\u6069\u8BFA\u57CE\u5E02\u5E9F\u589F\uFF0C\u4E0E\u738B\u56FD\u5176\u4F59\u57CE\u5E02\u4E00\u540C\u6BC1\u706D\u3002\u4EC5\u77E5\u5176\u540D\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("sallosh","ruin","dothraki-sea",[1264,500],1,{en:"Sallosh",zh:"\u8428\u6D1B\u4EC0"},["Sarnor"],{en:"A Sarnori port on the Shivering Sea coast, sacked and left empty when the khalasars reached the shore. Its position on the coast is approximate.",zh:"\u98A4\u6296\u6D77\u6CBF\u5CB8\u7684\u8428\u6069\u8BFA\u6E2F\u53E3\uFF0C\u5361\u62C9\u8428\u62B5\u8FBE\u6D77\u5CB8\u65F6\u906D\u6D17\u52AB\u5E76\u88AB\u5F03\u7F6E\u3002\u6D77\u5CB8\u4E0A\u7684\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("saath","town","dothraki-sea",[1404,476],1,{en:"Saath",zh:"\u8428\u65AF"},["Sarnor"],{en:"The last surviving city of the Sarnori, a walled port on the Shivering Sea. It is said to endure because traders from Lorath and Ibben protect it; it is a shadow of the old kingdom.",zh:"\u8428\u6069\u8BFA\u4EBA\u4EC5\u5B58\u7684\u57CE\u5E02\uFF0C\u98A4\u6296\u6D77\u8FB9\u4E00\u5EA7\u6709\u57CE\u5899\u7684\u6E2F\u53E3\u3002\u636E\u8BF4\u5B83\u80FD\u5E78\u5B58\uFF0C\u662F\u56E0\u4E3A\u6D1B\u62C9\u65AF\u4E0E\u4F0A\u73ED\u7684\u5546\u4EBA\u52A0\u4EE5\u5E87\u62A4\uFF1B\u4E0E\u6614\u65E5\u738B\u56FD\u76F8\u6BD4\u5DF2\u662F\u6B8B\u5F71\u3002"},["twoiaf"],"low"),e("field-of-crows","battle","dothraki-sea",[1300,712],1,{en:"Field of Crows",zh:"\u7FA4\u9E26\u4E4B\u91CE"},["Sarnor"],{en:"The battlefield where the host of Sarnor was broken by the united khalasars, a defeat that doomed the kingdom of the Tall Men. The site is placed here only roughly.",zh:"\u8428\u6069\u8BFA\u5927\u519B\u88AB\u8054\u5408\u8D77\u6765\u7684\u5404\u5361\u62C9\u8428\u51FB\u6E83\u4E4B\u5730\uFF0C\u8FD9\u4E00\u8D25\u6CE8\u5B9A\u4E86\u201C\u9AD8\u4EBA\u201D\u738B\u56FD\u7684\u706D\u4EA1\u3002\u56FE\u4E2D\u4F4D\u7F6E\u4EC5\u4E3A\u5927\u81F4\u3002"},["twoiaf"],"low"),e("lhazosh","town","dothraki-sea",[1584,1072],1,{en:"Lhazosh",zh:"\u62C9\u4F50\u4EC0"},["Lhazar","\u62C9\u672D"],{en:"A town of Lhazar, the land of the Lamb Men who herd sheep and worship the Great Shepherd. The peaceful Lhazareen are a favoured prey of Dothraki slavers. Known from the world history; position approximate.",zh:"\u62C9\u672D\u7684\u57CE\u9547\u3002\u62C9\u672D\u662F\u201C\u7F8A\u4EBA\u201D\u7684\u6545\u4E61\uFF0C\u4ED6\u4EEC\u653E\u7267\u7F8A\u7FA4\u3001\u5D07\u62DC\u4F1F\u5927\u7267\u7F8A\u4EBA\uFF0C\u6027\u60C5\u6E29\u548C\uFF0C\u5E38\u906D\u591A\u65AF\u62C9\u514B\u4EBA\u63B3\u63A0\u4E3A\u5974\u3002\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("hesh","town","dothraki-sea",[1520,1132],1,{en:"Hesh",zh:"\u8D6B\u4EC0"},["Lhazar","\u62C9\u672D"],{en:"One of the few towns of Lhazar, set among the hills and pastures between the Dothraki Sea and Slaver's Bay. Little is recorded beyond its name; position approximate.",zh:"\u62C9\u672D\u4E3A\u6570\u4E0D\u591A\u7684\u57CE\u9547\u4E4B\u4E00\uFF0C\u4F4D\u4E8E\u591A\u65AF\u62C9\u514B\u6D77\u4E0E\u5974\u96B6\u6E7E\u4E4B\u95F4\u7684\u4E18\u9675\u7267\u5730\u3002\u9664\u540D\u5B57\u5916\u6240\u77E5\u751A\u5C11\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("kosrak","town","dothraki-sea",[1606,1150],1,{en:"Kosrak",zh:"\u79D1\u65AF\u62C9\u514B"},["Lhazar","\u62C9\u672D"],{en:"A Lhazareen town in the south of the Lamb Men's country, near the edge of the Red Waste. Known only from the world history; position approximate.",zh:"\u7F8A\u4EBA\u56FD\u5EA6\u5357\u90E8\u7684\u62C9\u672D\u57CE\u9547\uFF0C\u9760\u8FD1\u7EA2\u8272\u8352\u539F\u8FB9\u7F18\u3002\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("bayasabhad","city","dothraki-sea",[1962,944],1,{en:"Bayasabhad",zh:"\u5DF4\u4E9A\u8428\u5DF4\u5FB7"},["Patrimony of Hyrkoon","\u6D77\u5C14\u5B54"],{en:"One of the three cities of the Patrimony of Hyrkoon, on the western side of the Bone Mountains. The Hyrkoon cities are known for warrior women and for guarding the passes against the Dothraki. Known from the world history; position approximate.",zh:"\u6D77\u5C14\u5B54\u7956\u5730\u4E09\u57CE\u4E4B\u4E00\uFF0C\u4F4D\u4E8E\u9AB8\u9AA8\u5C71\u8109\u897F\u4FA7\u3002\u6D77\u5C14\u5B54\u8BF8\u57CE\u4EE5\u5973\u6218\u58EB\u95FB\u540D\uFF0C\u627C\u5B88\u5C71\u53E3\u62B5\u5FA1\u591A\u65AF\u62C9\u514B\u4EBA\u3002\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("samyriana","city","dothraki-sea",[1988,1036],1,{en:"Samyriana",zh:"\u8428\u7C73\u91CC\u4E9A\u7EB3"},["Patrimony of Hyrkoon","\u6D77\u5C14\u5B54"],{en:"A city of the Patrimony of Hyrkoon in the foothills of the Bone Mountains, one of the few settled places between the grass sea and the east. Known only from the world history; position approximate.",zh:"\u9AB8\u9AA8\u5C71\u8109\u5C71\u9E93\u7684\u6D77\u5C14\u5B54\u7956\u5730\u57CE\u5E02\uFF0C\u662F\u8349\u6D77\u4E0E\u4E1C\u65B9\u4E4B\u95F4\u5C11\u6570\u5B9A\u5C45\u4E4B\u5730\u3002\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("kayakayanaya-hyrkoon","city","dothraki-sea",[1950,1120],1,{en:"Kayakayanaya (Hyrkoon)",zh:"\u5361\u4E9A\u5361\u4E9A\u7EB3\u4E9A\uFF08\u6D77\u5C14\u5B54\uFF09"},["Kayakayanaya","Patrimony of Hyrkoon","\u6D77\u5C14\u5B54"],{en:"The southernmost of the three Hyrkoon cities west of the Bone Mountains, said to be ruled by women. Not to be confused with Tall Trees Town in the Summer Isles. Known from the world history; position approximate.",zh:"\u9AB8\u9AA8\u5C71\u8109\u4EE5\u897F\u6D77\u5C14\u5B54\u4E09\u57CE\u4E2D\u6700\u5357\u7684\u4E00\u5EA7\uFF0C\u636E\u8BF4\u7531\u5973\u6027\u7EDF\u6CBB\u3002\u4E0D\u8981\u4E0E\u76DB\u590F\u7FA4\u5C9B\u7684\u9AD8\u6811\u9547\u6DF7\u6DC6\u3002\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("skahazadhan","river","slavers-bay",[1410,1060],3,{en:"The Skahazadhan",zh:"\u65AF\u5361\u54C8\u624E\u4E39\u6CB3"},["Skahazadhan river"],{en:"The broad brown river that runs out of the Dothraki Sea and enters Slaver's Bay at Meereen. The city draws its water from it and its fishing boats crowd the mouth; the grasslands begin just beyond its upper reaches.",zh:"\u53D1\u6E90\u4E8E\u591A\u65AF\u62C9\u514B\u6D77\u3001\u5728\u5F25\u6797\u6CE8\u5165\u5974\u96B6\u6E7E\u7684\u5BBD\u9614\u8910\u8272\u5927\u6CB3\u3002\u5F25\u6797\u53D6\u6C34\u4E8E\u6B64\uFF0C\u6CB3\u53E3\u6324\u6EE1\u6E14\u8239\uFF1B\u6EAF\u6D41\u800C\u4E0A\u4E0D\u8FDC\u4FBF\u662F\u8349\u539F\u3002"},["asos","adwd"],"medium"),e("worm","river","slavers-bay",[1342,1332],2,{en:"The Worm",zh:"\u8815\u866B\u6CB3"},["Worm river"],{en:"A sluggish river that winds past the red walls of Astapor into Slaver's Bay. The Astapori city stands on its bank.",zh:"\u4E00\u6761\u7F13\u6162\u873F\u8712\u7684\u6CB3\u6D41\uFF0C\u6D41\u7ECF\u963F\u65AF\u5854\u6CE2\u7684\u7EA2\u5899\u6CE8\u5165\u5974\u96B6\u6E7E\uFF0C\u963F\u65AF\u5854\u6CE2\u57CE\u4FBF\u5EFA\u5728\u6CB3\u5CB8\u4E0A\u3002"},["asos"],"medium"),e("old-ghis","ruin","slavers-bay",[1316,1410],3,{en:"Old Ghis",zh:"\u53E4\u5409\u65AF"},["Ghis","Ghiscari Empire","\u5409\u65AF","\u5409\u65AF\u5361\u5229\u5E1D\u56FD"],{en:"Ruins of the capital of the Old Empire of Ghis, which ruled these lands before Valyria. After five wars Valyria razed the city and sowed its fields with salt; the Ghiscari of the bay still call themselves sons of the Harpy in its memory.",zh:"\u53E4\u5409\u65AF\u5E1D\u56FD\u90FD\u57CE\u7684\u5E9F\u589F\uFF0C\u8BE5\u5E1D\u56FD\u5728\u74E6\u96F7\u5229\u4E9A\u4E4B\u524D\u7EDF\u6CBB\u6B64\u5730\u3002\u5386\u7ECF\u4E94\u6B21\u6218\u4E89\u540E\uFF0C\u74E6\u96F7\u5229\u4E9A\u5937\u5E73\u6B64\u57CE\uFF0C\u5E76\u5728\u7530\u5730\u91CC\u6492\u76D0\uFF1B\u5974\u96B6\u6E7E\u7684\u5409\u65AF\u5361\u5229\u4EBA\u81F3\u4ECA\u4ECD\u4EE5\u201C\u9E70\u8EAB\u5973\u5996\u4E4B\u5B50\u201D\u81EA\u5C45\uFF0C\u7F05\u6000\u65E7\u56FD\u3002"},["asos","twoiaf"],"medium"),e("new-ghis","city","slavers-bay",[1248,1352],3,{en:"New Ghis",zh:"\u65B0\u5409\u65AF"},["New Ghiscari","\u65B0\u5409\u65AF\u4EBA"],{en:"An island city off the Ghiscari coast that claims to be the heir of the Old Empire. Unlike the bay cities it keeps legions of free citizens drilled and armed in the old Ghiscari fashion.",zh:"\u5409\u65AF\u5361\u5229\u6D77\u5CB8\u5916\u7684\u4E00\u5EA7\u5C9B\u57CE\uFF0C\u81EA\u79F0\u53E4\u5E1D\u56FD\u7684\u7EE7\u627F\u8005\u3002\u4E0E\u6E7E\u5185\u8BF8\u57CE\u4E0D\u540C\uFF0C\u65B0\u5409\u65AF\u4FDD\u6709\u7531\u81EA\u7531\u516C\u6C11\u7EC4\u6210\u7684\u519B\u56E2\uFF0C\u6309\u53E4\u5409\u65AF\u65B9\u5F0F\u64CD\u7EC3\u4E0E\u88C5\u5907\u3002"},["asos","adwd","twoiaf"],"medium",{spoiler:{en:"New Ghis sent its legions to join the Yunkish siege of Meereen (ADWD).",zh:"\u65B0\u5409\u65AF\u6D3E\u519B\u56E2\u52A0\u5165\u6E0A\u51EF\u4EBA\u5BF9\u5F25\u6797\u7684\u56F4\u653B\uFF08\u5377\u4E94\uFF09\u3002"}}),e("khyzai-pass","pass","slavers-bay",[1470,1120],1,{en:"Khyzai Pass",zh:"\u51EF\u624E\u4F0A\u9698\u53E3"},["Khyzai"],{en:"A pass through the hills east of Meereen that carries the road toward Lhazar and the grasslands. It is mentioned in the novels' account of Meereen's hinterland; its exact course is not described.",zh:"\u5F25\u6797\u4EE5\u4E1C\u4E18\u9675\u4E2D\u7684\u4E00\u5904\u9698\u53E3\uFF0C\u901A\u5F80\u62C9\u672D\u4E0E\u8349\u539F\u7684\u9053\u8DEF\u7ECF\u6B64\u800C\u8FC7\u3002\u5C0F\u8BF4\u5728\u63CF\u5199\u5F25\u6797\u5468\u8FB9\u65F6\u66FE\u63D0\u53CA\uFF0C\u5177\u4F53\u8D70\u5411\u672A\u8BE6\u3002"},["adwd"],"low"),e("fourteen-flames","mountain","valyria",[1146,1440],3,{en:"The Fourteen Flames",zh:"\u5341\u56DB\u706B\u5CF0"},["Fourteen Fires"],{en:"The ring of fire-mountains at the heart of the Valyrian peninsula, where the Valyrians first tamed dragons. Their eruption in a single day was the Doom that destroyed the Freehold.",zh:"\u74E6\u96F7\u5229\u4E9A\u534A\u5C9B\u4E2D\u5FC3\u7684\u4E00\u5708\u706B\u5C71\uFF0C\u74E6\u96F7\u5229\u4E9A\u4EBA\u6700\u65E9\u5728\u6B64\u9A6F\u670D\u5DE8\u9F99\u3002\u5B83\u4EEC\u5728\u4E00\u65E5\u4E4B\u95F4\u540C\u65F6\u55B7\u53D1\uFF0C\u5373\u662F\u6467\u6BC1\u81EA\u7531\u5821\u5792\u7684\u672B\u65E5\u6D69\u52AB\u3002"},["agot","twoiaf"],"medium"),e("valyrian-groves","forest","valyria",[1126,1290],2,{en:"Lands of the Long Summer",zh:"\u957F\u590F\u4E4B\u5730"},["Long Summer","Valyrian peninsula"],{en:"The once rich and fertile country of the Valyrian peninsula, full of cities and estates of the dragonlords. Since the Doom it has been a haunted, half-empty land that few dare to cross.",zh:"\u74E6\u96F7\u5229\u4E9A\u534A\u5C9B\u4E0A\u6614\u65E5\u5BCC\u9976\u7684\u571F\u5730\uFF0C\u9F99\u738B\u7684\u57CE\u5E02\u4E0E\u5E84\u56ED\u904D\u5E03\u5176\u95F4\u3002\u672B\u65E5\u6D69\u52AB\u4E4B\u540E\uFF0C\u8FD9\u91CC\u6210\u4E86\u9B3C\u5F71\u5E62\u5E62\u3001\u4EBA\u70DF\u7A00\u5C11\u4E4B\u5730\uFF0C\u9C9C\u6709\u4EBA\u6562\u4E8E\u7A7F\u8D8A\u3002"},["acok","twoiaf"],"medium"),e("mantarys","city","valyria",[1150,1236],2,{en:"Mantarys",zh:"\u66FC\u5854\u91CC\u65AF"},["Demon Road","\u6076\u9B54\u4E4B\u8DEF"],{en:"A city on the Demon Road, the old Valyrian highway from Volantis to Meereen, near the neck of the peninsula. Travellers say that many of its people are born misshapen, a legacy of the Doom.",zh:"\u6076\u9B54\u4E4B\u8DEF\u4E0A\u7684\u57CE\u5E02\uFF0C\u9760\u8FD1\u534A\u5C9B\u7684\u9888\u90E8\uFF1B\u6076\u9B54\u4E4B\u8DEF\u662F\u74E6\u96F7\u5229\u4E9A\u4EBA\u4FEE\u5EFA\u7684\u5927\u9053\uFF0C\u81EA\u74E6\u5170\u63D0\u65AF\u76F4\u901A\u5F25\u6797\u3002\u65C5\u4EBA\u4F20\u8BF4\uFF0C\u53D7\u672B\u65E5\u6D69\u52AB\u9057\u7978\u5F71\u54CD\uFF0C\u57CE\u4E2D\u8BB8\u591A\u4EBA\u751F\u6765\u7578\u5F62\u3002"},["adwd","twoiaf"],"medium",{spoiler:{en:"Mantarys joined Yunkai's alliance against Daenerys (ADWD).",zh:"\u66FC\u5854\u91CC\u65AF\u52A0\u5165\u4E86\u6E0A\u51EF\u5BF9\u6297\u4E39\u59AE\u8389\u4E1D\u7684\u8054\u76DF\uFF08\u5377\u4E94\uFF09\u3002"}}),e("tolos","city","valyria",[1200,1262],2,{en:"Tolos",zh:"\u6258\u6D1B\u65AF"},["Tolosi"],{en:"A city on the shores of the Gulf of Grief whose slingers are sought as mercenaries. Its exact position is not given in the novels; it is placed here on the gulf's western coast.",zh:"\u60B2\u4F24\u6E7E\u6CBF\u5CB8\u7684\u57CE\u5E02\uFF0C\u5176\u6295\u77F3\u5175\u5E38\u88AB\u96C7\u4E3A\u4F63\u5175\u3002\u5C0F\u8BF4\u672A\u7ED9\u51FA\u786E\u5207\u4F4D\u7F6E\uFF0C\u6B64\u5904\u6807\u5728\u6D77\u6E7E\u897F\u5CB8\u3002"},["adwd","twoiaf"],"low",{spoiler:{en:"Tolos sent slingers to the Yunkish siege of Meereen (ADWD).",zh:"\u6258\u6D1B\u65AF\u6D3E\u6295\u77F3\u5175\u53C2\u52A0\u6E0A\u51EF\u4EBA\u5BF9\u5F25\u6797\u7684\u56F4\u653B\uFF08\u5377\u4E94\uFF09\u3002"}}),e("elyria","city","valyria",[1196,1314],1,{en:"Elyria",zh:"\u827E\u5229\u91CC\u4E9A"},["Elyrian"],{en:"A minor city on the Gulf of Grief, a neighbour of Tolos. It appears only in passing in the novels, and its position here is a guess.",zh:"\u60B2\u4F24\u6E7E\u7554\u7684\u5C0F\u57CE\uFF0C\u4E0E\u6258\u6D1B\u65AF\u76F8\u90BB\u3002\u5C0F\u8BF4\u4E2D\u53EA\u662F\u4E00\u7B14\u5E26\u8FC7\uFF0C\u6B64\u5904\u4F4D\u7F6E\u4E3A\u63A8\u6D4B\u3002"},["adwd","twoiaf"],"low",{spoiler:{en:"Elyria joined the alliance that marched on Meereen (ADWD).",zh:"\u827E\u5229\u91CC\u4E9A\u52A0\u5165\u4E86\u8FDB\u519B\u5F25\u6797\u7684\u8054\u76DF\uFF08\u5377\u4E94\uFF09\u3002"}}),e("oros","ruin","valyria",[1088,1344],1,{en:"Oros",zh:"\u5965\u7F57\u65AF"},["Lands of the Long Summer"],{en:"A Valyrian city of the Lands of the Long Summer, destroyed in the Doom. Only its name survives in the histories; the position shown is approximate.",zh:"\u957F\u590F\u4E4B\u5730\u7684\u4E00\u5EA7\u74E6\u96F7\u5229\u4E9A\u57CE\u5E02\uFF0C\u6BC1\u4E8E\u672B\u65E5\u6D69\u52AB\u3002\u53F2\u4E66\u4E2D\u4EC5\u7559\u5176\u540D\uFF0C\u56FE\u4E2D\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("tyria","ruin","valyria",[1172,1334],1,{en:"Tyria",zh:"\u63D0\u5229\u4E9A"},["Lands of the Long Summer"],{en:"Another Valyrian city of the peninsula lost in the Doom. It is known only by name; position approximate.",zh:"\u534A\u5C9B\u4E0A\u53E6\u4E00\u5EA7\u6BC1\u4E8E\u672B\u65E5\u6D69\u52AB\u7684\u74E6\u96F7\u5229\u4E9A\u57CE\u5E02\u3002\u4EC5\u77E5\u5176\u540D\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("isle-of-cedars","island","valyria",[1222,1430],2,{en:"Isle of Cedars",zh:"\u96EA\u677E\u5C9B"},["Isle of Cedars"],{en:"A wooded island at the mouth of the Gulf of Grief, once a flourishing Valyrian holding. The Doom's great wave drowned its people; now it is a wild place of cedar forests and ruins, and fleets use its sheltered waters as an anchorage.",zh:"\u60B2\u4F24\u6E7E\u53E3\u4E00\u5EA7\u6797\u6728\u8302\u5BC6\u7684\u5C9B\u5C7F\uFF0C\u66FE\u662F\u7E41\u8363\u7684\u74E6\u96F7\u5229\u4E9A\u9886\u5730\u3002\u672B\u65E5\u6D69\u52AB\u6380\u8D77\u7684\u5DE8\u6D6A\u6DF9\u6CA1\u4E86\u5C9B\u4E0A\u5C45\u6C11\uFF1B\u5982\u4ECA\u5C9B\u4E0A\u53EA\u5269\u96EA\u677E\u6797\u4E0E\u5E9F\u589F\uFF0C\u8FC7\u5F80\u8239\u961F\u5E38\u5728\u5176\u907F\u98CE\u6C34\u57DF\u4E0B\u951A\u3002"},["adwd","twoiaf"],"medium",{spoiler:{en:"Victarion Greyjoy's Iron Fleet regrouped here on its way to Meereen (ADWD).",zh:"\u7EF4\u514B\u5854\u5229\u6602\xB7\u845B\u96F7\u4E54\u4F0A\u7684\u94C1\u8230\u961F\u5728\u524D\u5F80\u5F25\u6797\u9014\u4E2D\u4E8E\u6B64\u96C6\u7ED3\uFF08\u5377\u4E94\uFF09\u3002"}}),e("velos","ruin","valyria",[1230,1438],1,{en:"Velos",zh:"\u7EF4\u6D1B\u65AF"},["Isle of Cedars"],{en:"The drowned city of the Isle of Cedars, said to have been destroyed in an hour when the sea rose at the Doom. Its existence and fate come from the histories; the ruins are not described in the novels.",zh:"\u96EA\u677E\u5C9B\u4E0A\u88AB\u6DF9\u6CA1\u7684\u57CE\u5E02\uFF0C\u636E\u8BF4\u672B\u65E5\u6D69\u52AB\u65F6\u6D77\u6C34\u66B4\u6DA8\uFF0C\u4E00\u4E2A\u65F6\u8FB0\u4E4B\u5185\u4FBF\u906D\u6BC1\u706D\u3002\u5176\u5B58\u5728\u4E0E\u7ED3\u5C40\u89C1\u4E8E\u53F2\u4E66\uFF0C\u5C0F\u8BF4\u672A\u63CF\u5199\u5176\u5E9F\u589F\u3002"},["twoiaf"],"low"),e("isle-of-tears","island","valyria",[1150,1561],2,{en:"Isle of Tears",zh:"\u6CEA\u4E4B\u5C9B"},["Isle of Tears"],{en:"A large island in the Summer Sea south of Valyria, once used by the Freehold as a place of exile and imprisonment. It is marked on the official maps but barely described.",zh:"\u74E6\u96F7\u5229\u4E9A\u4EE5\u5357\u3001\u590F\u65E5\u4E4B\u6D77\u4E2D\u7684\u5927\u5C9B\uFF0C\u636E\u79F0\u74E6\u96F7\u5229\u4E9A\u81EA\u7531\u5821\u5792\u66FE\u4EE5\u6B64\u4E3A\u6D41\u653E\u548C\u56DA\u7981\u4E4B\u5730\u3002\u5B98\u65B9\u5730\u56FE\u4E0A\u6709\u6807\u6CE8\uFF0C\u4F46\u63CF\u8FF0\u6781\u5C11\u3002"},["maps","twoiaf"],"low"),e("red-waste","desert","red-waste",[1760,1320],4,{en:"The Red Waste",zh:"\u7EA2\u8272\u8352\u539F"},["Red Desert","\u7EA2\u8272\u6C99\u6F20"],{en:"A desolate plain of red clay and stone between Lhazar and Qarth, with scarcely any water. The Dothraki fear to cross it, and the few ruined cities in it are the remains of peoples who died long ago.",zh:"\u62C9\u672D\u4E0E\u9B41\u5C14\u65AF\u4E4B\u95F4\u4E00\u7247\u7EA2\u571F\u4E0E\u788E\u77F3\u7684\u8352\u539F\uFF0C\u51E0\u4E4E\u65E0\u6C34\u53EF\u5BFB\u3002\u591A\u65AF\u62C9\u514B\u4EBA\u4E0D\u6562\u6DF1\u5165\uFF0C\u8352\u539F\u4E2D\u96F6\u661F\u7684\u5E9F\u57CE\u662F\u65E9\u5DF2\u6D88\u4EA1\u7684\u6C11\u65CF\u7559\u4E0B\u7684\u9057\u8FF9\u3002"},["acok","twoiaf"],"high",{spoiler:{en:"After Drogo's death, Daenerys led the remnant of her khalasar across the Red Waste toward Qarth (ACOK).",zh:"\u5353\u6208\u6B7B\u540E\uFF0C\u4E39\u59AE\u8389\u4E1D\u7387\u9886\u6B8B\u4F59\u7684\u5361\u62C9\u8428\u7A7F\u8D8A\u7EA2\u8272\u8352\u539F\uFF0C\u524D\u5F80\u9B41\u5C14\u65AF\uFF08\u5377\u4E8C\uFF09\u3002"}}),e("vaes-tolorro","ruin","red-waste",[1720,1300],3,{en:"Vaes Tolorro",zh:"\u7EF4\u65AF\xB7\u6258\u7F57\u82E5"},["City of Bones","\u767D\u9AA8\u4E4B\u57CE"],{en:"A ruined city in the Red Waste with pale walls, a spring still flowing and fruit trees gone wild. The Dothraki call it the City of Bones; who built it and why it died are unknown.",zh:"\u7EA2\u8272\u8352\u539F\u4E2D\u7684\u4E00\u5EA7\u5E9F\u57CE\uFF0C\u57CE\u5899\u82CD\u767D\uFF0C\u6CC9\u6C34\u5C1A\u5728\u6D41\u6DCC\uFF0C\u679C\u6811\u65E9\u5DF2\u8352\u751F\u3002\u591A\u65AF\u62C9\u514B\u4EBA\u79F0\u4E4B\u4E3A\u201C\u767D\u9AA8\u4E4B\u57CE\u201D\uFF1B\u5EFA\u9020\u8005\u662F\u8C01\u3001\u56E0\u4F55\u800C\u4EA1\uFF0C\u90FD\u5DF2\u65E0\u4EBA\u77E5\u6653\u3002"},["acok"],"medium",{spoiler:{en:"Daenerys's starving khalasar sheltered here, and from it she sent riders who found the way to Qarth (ACOK).",zh:"\u4E39\u59AE\u8389\u4E1D\u9965\u6E34\u4EA4\u52A0\u7684\u5361\u62C9\u8428\u5728\u6B64\u6816\u8EAB\uFF0C\u5979\u7531\u6B64\u6D3E\u51FA\u9A91\u624B\uFF0C\u627E\u5230\u4E86\u901A\u5F80\u9B41\u5C14\u65AF\u7684\u8DEF\uFF08\u5377\u4E8C\uFF09\u3002"}}),e("house-of-the-undying","sacred","eastern-essos",[1926,1500],2,{en:"House of the Undying",zh:"\u4E0D\u673D\u8005\u4E4B\u6BBF"},["Palace of Dust","\u5C18\u5BAB"],{en:"The windowless, dust-grey palace of the warlocks of Qarth, surrounded by black trees and said to be entered only through a single door. Inside, the Undying are said to show visions of past and future to those who drink the shade of the evening.",zh:"\u9B41\u5C14\u65AF\u672F\u58EB\u4EEC\u6CA1\u6709\u7A97\u6237\u7684\u7070\u8272\u5BAB\u6BBF\uFF0C\u56DB\u5468\u662F\u9ED1\u8272\u7684\u6811\uFF0C\u636E\u8BF4\u53EA\u6709\u4E00\u9053\u95E8\u53EF\u5165\u3002\u6BBF\u4E2D\u7684\u4E0D\u673D\u8005\u4F1A\u8BA9\u996E\u4E0B\u201C\u66AE\u5F71\u4E4B\u9152\u201D\u7684\u4EBA\u770B\u89C1\u8FC7\u53BB\u4E0E\u672A\u6765\u7684\u5E7B\u8C61\u3002"},["acok"],"medium",{spoiler:{en:"Daenerys entered it in ACOK and escaped when her dragon set the Undying aflame.",zh:"\u5377\u4E8C\u4E2D\u4E39\u59AE\u8389\u4E1D\u8D70\u8FDB\u6B64\u6BBF\uFF0C\u5979\u7684\u9F99\u711A\u70E7\u4E86\u4E0D\u673D\u8005\uFF0C\u5979\u624D\u5F97\u4EE5\u8131\u8EAB\u3002"}}),e("bone-mountains","mountain","far-east",[2080,900],4,{en:"The Bone Mountains",zh:"\u9AB8\u9AA8\u5C71\u8109"},["Bones"],{en:"A vast range running north to south that walls the east of the known world off from the Dothraki Sea and the Red Waste. Only a few passes cross it, and old fortresses guard them.",zh:"\u4E00\u6761\u5357\u5317\u8D70\u5411\u7684\u5DE8\u5927\u5C71\u8109\uFF0C\u5C06\u5DF2\u77E5\u4E16\u754C\u7684\u4E1C\u65B9\u4E0E\u591A\u65AF\u62C9\u514B\u6D77\u3001\u7EA2\u8272\u8352\u539F\u9694\u5F00\u3002\u53EA\u6709\u5C11\u6570\u5C71\u53E3\u53EF\u4EE5\u901A\u8FC7\uFF0C\u7531\u53E4\u8001\u8981\u585E\u628A\u5B88\u3002"},["agot","twoiaf"],"medium"),e("grey-waste","desert","far-east",[2520,700],3,{en:"The Grey Waste",zh:"\u7070\u8272\u8352\u539F"},["Grey Waste"],{en:"A bleak, barren desert north of Yi Ti, beyond the Bone Mountains, said to be haunted by ghouls and outlaws. It appears only in the world history.",zh:"\u9AB8\u9AA8\u5C71\u8109\u4EE5\u4E1C\u3001\u5937\u5730\u4EE5\u5317\u7684\u8352\u51C9\u4E0D\u6BDB\u4E4B\u5730\uFF0C\u4F20\u8BF4\u6709\u98DF\u5C38\u9B3C\u548C\u4EA1\u547D\u4E4B\u5F92\u51FA\u6CA1\u3002\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002"},["twoiaf"],"low"),e("mountains-of-the-morn","mountain","far-east",[2970,1060],2,{en:"Mountains of the Morn",zh:"\u6668\u66E6\u5C71\u8109"},["Morn"],{en:"Mountains at the eastern edge of Yi Ti, beyond which lie lands no one in the novels has seen. They are named in the world history and on the official maps.",zh:"\u5937\u5730\u4E1C\u7F18\u7684\u7FA4\u5C71\uFF0C\u5C71\u90A3\u8FB9\u662F\u5C0F\u8BF4\u4E2D\u65E0\u4EBA\u89C1\u8FC7\u7684\u571F\u5730\u3002\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u4E0E\u5B98\u65B9\u5730\u56FE\u3002"},["maps","twoiaf"],"low"),e("five-forts","ruin","far-east",[2760,820],2,{en:"The Five Forts",zh:"\u4E94\u5821"},["Five Forts"],{en:"Five immense black-stone fortresses at the north-eastern edge of Yi Ti, said to have been raised in a legendary age to guard against something beyond the Grey Waste. The histories treat their origin as a mystery; the position here is approximate.",zh:"\u5937\u5730\u4E1C\u5317\u8FB9\u9672\u7684\u4E94\u5EA7\u5DE8\u5927\u9ED1\u77F3\u8981\u585E\uFF0C\u76F8\u4F20\u5EFA\u4E8E\u4F20\u8BF4\u65F6\u4EE3\uFF0C\u7528\u4EE5\u9632\u5907\u7070\u8272\u8352\u539F\u4E4B\u5916\u7684\u67D0\u79CD\u5A01\u80C1\u3002\u53F2\u4E66\u89C6\u5176\u6765\u5386\u4E3A\u8C1C\uFF0C\u56FE\u4E2D\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("tiqui","city","far-east",[2380,1020],1,{en:"Tiqui",zh:"\u63D0\u57FA"},["Yi Ti","\u5937\u5730"],{en:"A city of Yi Ti mentioned in the world history, inland from the Jade Sea. Nothing about it is described in the novels; position approximate.",zh:"\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u4E2D\u63D0\u53CA\u7684\u5937\u5730\u57CE\u5E02\uFF0C\u4F4D\u4E8E\u7389\u6D77\u4EE5\u5317\u7684\u5185\u9646\u3002\u5C0F\u8BF4\u672A\u6709\u63CF\u5199\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("si-qo","city","far-east",[2300,1392],2,{en:"Si Qo",zh:"\u897F\u67EF"},["Yi Ti","\u5937\u5730"],{en:"A city of Yi Ti on or near the Jade Sea coast, named in the histories as one of the empire's great cities. Little else is recorded; position approximate.",zh:"\u7389\u6D77\u6CBF\u5CB8\u6216\u9644\u8FD1\u7684\u4E00\u5EA7\u5937\u5730\u57CE\u5E02\uFF0C\u53F2\u4E66\u4E2D\u5217\u4E3A\u5E1D\u56FD\u5927\u57CE\u4E4B\u4E00\u3002\u6B64\u5916\u6240\u77E5\u751A\u5C11\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("great-moraq","island","far-east",[2310,1590],3,{en:"Great Moraq",zh:"\u5927\u83AB\u62C9\u514B\u5C9B"},["Moraq"],{en:"A long, forested island in the Jade Sea, a waypoint on the sea lanes between Qarth and the far east. It is named in the novels and maps but barely described.",zh:"\u7389\u6D77\u4E2D\u72ED\u957F\u800C\u68EE\u6797\u5BC6\u5E03\u7684\u5C9B\u5C7F\uFF0C\u662F\u9B41\u5C14\u65AF\u4E0E\u8FDC\u4E1C\u4E4B\u95F4\u822A\u8DEF\u4E0A\u7684\u4E2D\u8F6C\u7AD9\u3002\u5C0F\u8BF4\u4E0E\u5730\u56FE\u4E2D\u6709\u63D0\u53CA\uFF0C\u4F46\u51E0\u4E4E\u6CA1\u6709\u63CF\u5199\u3002"},["acok","maps","twoiaf"],"low"),e("trader-town","town","far-east",[2290,1574],1,{en:"Trader Town",zh:"\u5546\u4EBA\u9547"},["Great Moraq"],{en:"A port where foreign merchants are permitted to trade, placed here on Great Moraq. Its attribution and position are uncertain; it is known only from the world history.",zh:"\u5141\u8BB8\u5916\u56FD\u5546\u4EBA\u4EA4\u6613\u7684\u6E2F\u53E3\uFF0C\u6B64\u5904\u6807\u4E8E\u5927\u83AB\u62C9\u514B\u5C9B\u3002\u5176\u5F52\u5C5E\u4E0E\u4F4D\u7F6E\u5747\u4E0D\u786E\u5B9A\uFF0C\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002"},["twoiaf"],"low"),e("leng","island","far-east",[2670,1739],3,{en:"Leng",zh:"\u51B7\u5C9B"},["Lengii","\u51B7\u5C9B\u4EBA"],{en:"A large jungle island in the Jade Sea south of Asshai. The tall Lengii are said to be descended from a lost race, and ruins in the island's jungles are spoken of with dread.",zh:"\u4E9A\u590F\u4EE5\u5357\u3001\u7389\u6D77\u4E2D\u7684\u4E00\u5EA7\u4E1B\u6797\u5927\u5C9B\u3002\u8EAB\u6750\u9AD8\u5927\u7684\u51B7\u5C9B\u4EBA\u636E\u8BF4\u662F\u67D0\u4E2A\u5931\u843D\u6C11\u65CF\u7684\u540E\u88D4\uFF0C\u5C9B\u4E0A\u4E1B\u6797\u4E2D\u7684\u5E9F\u589F\u4EE4\u4EBA\u8C08\u4E4B\u8272\u53D8\u3002"},["acok","adwd","twoiaf"],"low"),e("the-shadow","mountain","far-east",[2900,1430],3,{en:"The Shadow",zh:"\u9634\u5F71\u5C71\u8109"},["Shadow Lands","\u9634\u5F71\u4E4B\u5730"],{en:"The dark mountainous country behind Asshai, the Shadow Lands, where even sorcerers go warily. Tales tell of dragons, wyverns and dead cities in its depths.",zh:"\u4E9A\u590F\u80CC\u540E\u5E7D\u6697\u7684\u5C71\u5730\uFF0C\u5373\u9634\u5F71\u4E4B\u5730\uFF0C\u8FDE\u672F\u58EB\u4E5F\u4E0D\u6562\u6389\u4EE5\u8F7B\u5FC3\u3002\u4F20\u8BF4\u5176\u6DF1\u5904\u6709\u9F99\u3001\u98DE\u9F99\u4E0E\u6B7B\u57CE\u3002"},["acok","twoiaf"],"low"),e("ash","river","far-east",[2810,1546],2,{en:"The Ash",zh:"\u7070\u70EC\u6CB3"},["River Ash"],{en:"The river that flows out of the Shadow and past Asshai into the Jade Sea, its waters said to be black, warm and poisonous. It is known from the world history.",zh:"\u53D1\u6E90\u4E8E\u9634\u5F71\u5C71\u8109\u3001\u6D41\u7ECF\u4E9A\u590F\u6CE8\u5165\u7389\u6D77\u7684\u6CB3\u6D41\uFF0C\u636E\u8BF4\u6CB3\u6C34\u4E4C\u9ED1\u3001\u6E29\u70ED\u800C\u6709\u6BD2\u3002\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002"},["twoiaf"],"low"),e("stygai","ruin","far-east",[2858,1464],1,{en:"Stygai",zh:"\u65AF\u6CF0\u76D6"},["Corpse City"],{en:"A dead city deep in the Shadow, upriver from Asshai, said to be shunned even by the shadowbinders. It appears only in the world history; position approximate.",zh:"\u9634\u5F71\u5C71\u8109\u6DF1\u5904\u3001\u4E9A\u590F\u4E0A\u6E38\u7684\u4E00\u5EA7\u6B7B\u57CE\uFF0C\u636E\u8BF4\u8FDE\u7F1A\u5F71\u58EB\u4E5F\u907F\u800C\u8FDC\u4E4B\u3002\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("ibben","island","shivering-sea",[1679,285],3,{en:"Ibben",zh:"\u4F0A\u73ED"},["Ibbenese","\u4F0A\u73ED\u4EBA"],{en:"A large, cold island in the Shivering Sea, home of a stocky, hairy people distinct from other men. The Ibbenese are whalers, sealers and traders; the island's hills are wooded and its coast hard.",zh:"\u98A4\u6296\u6D77\u4E2D\u5BD2\u51B7\u7684\u5927\u5C9B\uFF0C\u5C9B\u6C11\u8EAB\u6750\u77EE\u58EE\u3001\u6BDB\u53D1\u6D53\u5BC6\uFF0C\u4E0E\u5176\u4ED6\u4EBA\u79CD\u8FE5\u7136\u6709\u522B\u3002\u4F0A\u73ED\u4EBA\u4EE5\u6355\u9CB8\u3001\u730E\u6D77\u8C79\u548C\u7ECF\u5546\u4E3A\u751F\uFF1B\u5C9B\u4E0A\u4E18\u9675\u6797\u6728\u8302\u5BC6\uFF0C\u6D77\u5CB8\u9669\u5CFB\u3002"},["agot","affc","twoiaf"],"medium"),e("ib-nor","town","shivering-sea",[1600,300],1,{en:"Ib Nor",zh:"\u4F0A\u5E03\u8BFA"},["Ibben"],{en:"A town of Ibben named in the world history. Nothing else is known of it, and its position on the island is a guess.",zh:"\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u4E2D\u63D0\u5230\u7684\u4F0A\u73ED\u57CE\u9547\u3002\u6B64\u5916\u4E00\u65E0\u6240\u77E5\uFF0C\u5C9B\u4E0A\u4F4D\u7F6E\u4E3A\u63A8\u6D4B\u3002"},["twoiaf"],"low"),e("ib-sar","town","shivering-sea",[1770,292],1,{en:"Ib Sar",zh:"\u4F0A\u5E03\u8428"},["Ibben"],{en:"Another town of Ibben named in the world history; its location on the island is not known and is placed here arbitrarily.",zh:"\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u4E2D\u63D0\u5230\u7684\u53E6\u4E00\u5EA7\u4F0A\u73ED\u57CE\u9547\uFF1B\u5C9B\u4E0A\u4F4D\u7F6E\u4E0D\u8BE6\uFF0C\u6B64\u5904\u4E3A\u793A\u610F\u3002"},["twoiaf"],"low"),e("jhala","island","summer-isles",[429,1499],3,{en:"Jhala",zh:"\u8D3E\u62C9\u5C9B"},["Summer Isles","\u76DB\u590F\u7FA4\u5C9B"],{en:"One of the three great Summer Isles, nearest to Westeros, and home of Tall Trees Town. Like its neighbours it is green, warm and densely forested.",zh:"\u76DB\u590F\u7FA4\u5C9B\u4E09\u5EA7\u5927\u5C9B\u4E4B\u4E00\uFF0C\u8DDD\u7EF4\u65AF\u7279\u6D1B\u6700\u8FD1\uFF0C\u9AD8\u6811\u9547\u5373\u5728\u6B64\u5C9B\u3002\u4E0E\u90BB\u5C9B\u4E00\u6837\u6E29\u6696\u9752\u7FE0\uFF0C\u6797\u6728\u7E41\u8302\u3002"},["twoiaf","maps"],"medium"),e("walano","island","summer-isles",[521,1560],3,{en:"Walano",zh:"\u74E6\u62C9\u8BFA\u5C9B"},["Summer Isles","\u76DB\u590F\u7FA4\u5C9B"],{en:"The largest of the Summer Isles. The islanders' princes rule its vales, and their fine ships, fruits and birds of many colours are traded across the seas.",zh:"\u76DB\u590F\u7FA4\u5C9B\u4E2D\u6700\u5927\u7684\u5C9B\u5C7F\u3002\u5C9B\u4E0A\u5404\u6CB3\u8C37\u7531\u738B\u516C\u6CBB\u7406\uFF0C\u6240\u4EA7\u7684\u826F\u8239\u3001\u6C34\u679C\u4E0E\u4E94\u5F69\u98DE\u9E1F\u8FDC\u9500\u5404\u5730\u3002"},["twoiaf","maps"],"medium"),e("omboru","island","summer-isles",[613,1528],2,{en:"Omboru",zh:"\u6B27\u59C6\u6CE2\u9C81\u5C9B"},["Summer Isles","\u76DB\u590F\u7FA4\u5C9B"],{en:"The easternmost of the three great Summer Isles, the smallest of them. It is named on the maps but little described.",zh:"\u76DB\u590F\u7FA4\u5C9B\u4E09\u5EA7\u5927\u5C9B\u4E2D\u6700\u4E1C\u3001\u4E5F\u6700\u5C0F\u7684\u4E00\u5EA7\u3002\u5730\u56FE\u4E0A\u6709\u6807\u6CE8\uFF0C\u4F46\u63CF\u8FF0\u751A\u5C11\u3002"},["twoiaf","maps"],"low"),e("red-flower-vale","town","summer-isles",[420,1487],1,{en:"Red Flower Vale",zh:"\u7EA2\u82B1\u8C37"},["Jalabhar Xho"],{en:"A vale of the Summer Isles whose exiled prince, Jalabhar Xho, lingers at the court in King's Landing hoping for help to reclaim it. Its island is not stated; it is placed on Jhala as a guess.",zh:"\u76DB\u590F\u7FA4\u5C9B\u7684\u4E00\u5904\u6CB3\u8C37\uFF0C\u5176\u6D41\u4EA1\u738B\u5B50\u8D3E\u62C9\u5DF4\xB7\u68AD\u5BC4\u5C45\u541B\u4E34\u5BAB\u5EF7\uFF0C\u76FC\u671B\u501F\u5175\u593A\u56DE\u6545\u571F\u3002\u6240\u5728\u5C9B\u5C7F\u4E66\u4E2D\u672A\u660E\u8A00\uFF0C\u6B64\u5904\u63A8\u6D4B\u6807\u4E8E\u8D3E\u62C9\u5C9B\u3002"},["agot","acok"],"low",{houses:["xho"]}),e("lotus-point","town","summer-isles",[494,1574],1,{en:"Lotus Point",zh:"\u83B2\u82B1\u89D2"},["Summer Isles"],{en:"A port of the Summer Isles named in the world history. Its island is uncertain; it is shown here on Walano.",zh:"\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u4E2D\u63D0\u5230\u7684\u76DB\u590F\u7FA4\u5C9B\u6E2F\u53E3\u3002\u6240\u5728\u5C9B\u5C7F\u4E0D\u786E\u5B9A\uFF0C\u6B64\u5904\u6807\u4E8E\u74E6\u62C9\u8BFA\u5C9B\u3002"},["twoiaf"],"low"),e("ebonhead","town","summer-isles",[552,1548],1,{en:"Ebonhead",zh:"\u4E4C\u6728\u5CAC"},["Summer Isles"],{en:"A place in the Summer Isles named in the world history, presumably for the ebony that grows there. Its location is uncertain; it is shown on Walano.",zh:"\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u4E2D\u63D0\u5230\u7684\u76DB\u590F\u7FA4\u5C9B\u5730\u540D\uFF0C\u5927\u6982\u56E0\u51FA\u4EA7\u4E4C\u6728\u800C\u5F97\u540D\u3002\u4F4D\u7F6E\u4E0D\u786E\u5B9A\uFF0C\u6B64\u5904\u6807\u4E8E\u74E6\u62C9\u8BFA\u5C9B\u3002"},["twoiaf"],"low"),e("last-lament","town","summer-isles",[528,1575],1,{en:"Last Lament",zh:"\u7EC8\u54C0\u9547"},["Summer Isles"],{en:"A town of the Summer Isles with a mournful name, known only from the world history. Its location is uncertain; it is shown on Walano.",zh:"\u76DB\u590F\u7FA4\u5C9B\u4E0A\u4E00\u4E2A\u540D\u5B57\u54C0\u4F24\u7684\u57CE\u9547\uFF0C\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002\u4F4D\u7F6E\u4E0D\u786E\u5B9A\uFF0C\u6B64\u5904\u6807\u4E8E\u74E6\u62C9\u8BFA\u5C9B\u3002"},["twoiaf"],"low"),e("naath","island","summer-isles",[880,1700],3,{en:"Naath",zh:"\u7EB3\u65AF"},["Isle of Butterflies","\u8774\u8776\u5C9B","Peaceful People"],{en:"The Isle of Butterflies, home of the gentle Peaceful People who refuse to kill and make music instead of war. Slavers raid it often; outsiders who stay too long fall to a fever the islanders say their butterfly god sends.",zh:"\u201C\u8774\u8776\u5C9B\u201D\uFF0C\u6E29\u548C\u7684\u201C\u548C\u5E73\u4E4B\u6C11\u201D\u7684\u6545\u4E61\uFF0C\u4ED6\u4EEC\u62D2\u7EDD\u6740\u622E\uFF0C\u4EE5\u97F3\u4E50\u4EE3\u66FF\u6218\u4E89\u3002\u5974\u96B6\u8D29\u5B50\u5C61\u5C61\u524D\u6765\u52AB\u63A0\uFF1B\u5916\u4EBA\u4E45\u7559\u5219\u4F1A\u67D3\u4E0A\u4E00\u79CD\u70ED\u75C5\uFF0C\u5C9B\u6C11\u8BF4\u90A3\u662F\u8774\u8776\u795E\u964D\u4E0B\u7684\u3002"},["asos","adwd","twoiaf"],"medium"),e("basilisk-isles","island","summer-isles",[1e3,1650],3,{en:"Basilisk Isles",zh:"\u86C7\u8725\u7FA4\u5C9B"},["Basilisk Islands"],{en:"A scatter of hot, fever-ridden islands off the coast of Sothoryos, a notorious nest of corsairs and slavers. The pirates of the isles raid as far as Naath and the coasts of the Summer Sea.",zh:"\u7D22\u65AF\u7F57\u65AF\u6D77\u5CB8\u5916\u4E00\u4E32\u708E\u70ED\u591A\u7634\u7684\u5C9B\u5C7F\uFF0C\u662F\u81ED\u540D\u662D\u8457\u7684\u6D77\u76D7\u4E0E\u5974\u96B6\u8D29\u5B50\u5DE2\u7A74\u3002\u7FA4\u5C9B\u7684\u6D77\u76D7\u52AB\u63A0\u8FDC\u53CA\u7EB3\u65AF\u4E0E\u590F\u65E5\u4E4B\u6D77\u6CBF\u5CB8\u3002"},["acok","asos","twoiaf"],"medium"),e("gogossos","town","summer-isles",[1034,1664],1,{en:"Gogossos",zh:"\u6208\u6208\u7D22\u65AF"},["Basilisk Isles"],{en:"The largest of the Basilisk Isles and its chief slave port, notorious for its cruelty and for plagues bred in its pens. Known mostly from the world history; position approximate.",zh:"\u86C7\u8725\u7FA4\u5C9B\u4E2D\u6700\u5927\u7684\u5C9B\u53CA\u5176\u4E3B\u8981\u5974\u96B6\u6E2F\uFF0C\u4EE5\u6B8B\u66B4\u548C\u5974\u96B6\u5708\u4E2D\u6ECB\u751F\u7684\u761F\u75AB\u95FB\u540D\u3002\u4E3B\u8981\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("isle-of-toads","island","summer-isles",[1062,1640],1,{en:"Isle of Toads",zh:"\u87FE\u870D\u5C9B"},["Basilisk Isles"],{en:"A small island of the Basilisk Isles where an ancient stone idol, a monstrous toad, still stands. Its makers are unknown; it appears in the world history.",zh:"\u86C7\u8725\u7FA4\u5C9B\u4E2D\u7684\u5C0F\u5C9B\uFF0C\u5C9B\u4E0A\u81F3\u4ECA\u77D7\u7ACB\u7740\u4E00\u5C0A\u53E4\u8001\u7684\u77F3\u50CF\u2014\u2014\u4E00\u53EA\u5DE8\u5927\u7684\u87FE\u870D\u3002\u96D5\u523B\u8005\u4E0D\u660E\uFF0C\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002"},["twoiaf"],"low"),e("zamettar","ruin","summer-isles",[1132,1806],1,{en:"Zamettar",zh:"\u624E\u6885\u5854"},["Sothoryos","\u7D22\u65AF\u7F57\u65AF"],{en:"A ruined Ghiscari outpost on the north coast of Sothoryos at the mouth of the Zamoyos. The jungle and its fevers drove the colonists out; it is known from the world history.",zh:"\u7D22\u65AF\u7F57\u65AF\u5317\u5CB8\u3001\u624E\u83AB\u7EA6\u65AF\u6CB3\u53E3\u7684\u5409\u65AF\u5361\u5229\u524D\u54E8\u5E9F\u589F\u3002\u4E1B\u6797\u4E0E\u70ED\u75C5\u8FEB\u4F7F\u6B96\u6C11\u8005\u64A4\u79BB\u3002\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\u3002"},["twoiaf"],"low"),e("gorosh","ruin","summer-isles",[1298,1816],1,{en:"Gorosh",zh:"\u6208\u7F57\u4EC0"},["Sothoryos","\u7D22\u65AF\u7F57\u65AF"],{en:"Another of the old Ghiscari footholds on the coast of Sothoryos, long abandoned. Known only from the world history; position approximate.",zh:"\u7D22\u65AF\u7F57\u65AF\u6D77\u5CB8\u4E0A\u53E6\u4E00\u5904\u65E9\u5DF2\u5E9F\u5F03\u7684\u53E4\u5409\u65AF\u5361\u5229\u636E\u70B9\u3002\u4EC5\u89C1\u4E8E\u300A\u51B0\u4E0E\u706B\u4E4B\u6B4C\u7684\u4E16\u754C\u300B\uFF0C\u4F4D\u7F6E\u4E3A\u4F30\u8BA1\u3002"},["twoiaf"],"low"),e("yeen","ruin","summer-isles",[1164,1878],2,{en:"Yeen",zh:"\u4F0A\u6069"},["Sothoryos","\u7D22\u65AF\u7F57\u65AF"],{en:"An ancient, empty city of oily black stone in the jungles of Sothoryos, older than any known people. The jungle has never reclaimed it, and those who try to settle there are said to vanish.",zh:"\u7D22\u65AF\u7F57\u65AF\u4E1B\u6797\u4E2D\u4E00\u5EA7\u53E4\u8001\u7684\u7A7A\u57CE\uFF0C\u4EE5\u6CB9\u4EAE\u7684\u9ED1\u77F3\u5EFA\u6210\uFF0C\u6BD4\u4EFB\u4F55\u5DF2\u77E5\u6C11\u65CF\u90FD\u66F4\u53E4\u8001\u3002\u4E1B\u6797\u59CB\u7EC8\u672A\u80FD\u5C06\u5176\u541E\u6CA1\uFF0C\u4F20\u8BF4\u5728\u6B64\u5B9A\u5C45\u7684\u4EBA\u90FD\u4F1A\u6D88\u5931\u3002"},["twoiaf"],"low"),e("green-hell","forest","summer-isles",[1100,1900],3,{en:"The Green Hell",zh:"\u7EFF\u8272\u5730\u72F1"},["Sothoryos jungle","\u7D22\u65AF\u7F57\u65AF"],{en:"The steaming jungle that covers northern Sothoryos, full of fevers, poisonous creatures and stranger things. Every attempt to colonise it, Ghiscari, Valyrian or other, has failed.",zh:"\u8986\u76D6\u7D22\u65AF\u7F57\u65AF\u5317\u90E8\u7684\u6E7F\u70ED\u4E1B\u6797\uFF0C\u70ED\u75C5\u3001\u6BD2\u7269\u4E0E\u66F4\u8BE1\u5F02\u4E4B\u7269\u5145\u65A5\u5176\u95F4\u3002\u5409\u65AF\u5361\u5229\u4EBA\u3001\u74E6\u96F7\u5229\u4E9A\u4EBA\u7B49\u5386\u6B21\u6B96\u6C11\u5C1D\u8BD5\u65E0\u4E00\u6210\u529F\u3002"},["twoiaf"],"low")]};export{m as default};
